from reference import Task
N=200
INSTANCES=30
random.seed(0)
seeds=random.sample(range(10**9), INSTANCES)

def run(func):
    t=0
    for seed in seeds:
        prob=Task().generate_problem(n=N, random_seed=seed)
        p=copy.deepcopy(prob)
        t0=time.perf_counter_ns(); func(p); t+=time.perf_counter_ns()-t0
